import type { Transform } from './types.js'

/** A single transform's result within {@link RunTransformsResult}. */
export type TransformResult = {
  error?: Error
  filesChanged: string[]
  name: string
  notes?: string[]
}

/** The aggregate result returned by {@link runTransforms}. */
export type RunTransformsResult = {
  failed: boolean
  results: TransformResult[]
}

/**
 * Runs all supplied transforms in order against a ts-morph `Project`.
 *
 * Execution continues past any transform that throws, collecting a result for
 * every transform. Returns `failed=true` if any transform threw an error.
 */
export async function runTransforms({
  project,
  transforms,
}: {
  project: Project
  transforms: Transform[]
}): Promise<RunTransformsResult> {
  const results: TransformResult[] = []
  let failed = false

  for (const transform of transforms) {
    try {
      const output = await transform.apply({ project })
      const result: TransformResult = {
        name: transform.name,
        filesChanged: output.filesChanged,
      }
      if (output.notes) {
        result.notes = output.notes
      }
      results.push(result)
    } catch (err) {
      failed = true
      results.push({
        name: transform.name,
        error: err instanceof Error ? err : new Error(String(err)),
        filesChanged: [],
      })
    }
  }

  return { failed, results }
}
