import type { Transform } from '../types.js'

/**
 * Test helper that creates an in-memory ts-morph `Project` containing the given
 * source string as a single TypeScript file, applies the transform, and
 * returns the resulting file's source text.
 */
export async function runTransform({
  filename = 'input.ts',
  source,
  transform,
}: {
  filename?: string
  source: string
  transform: Transform
}): Promise<string> {
  const project = new Project({ useInMemoryFileSystem: true })
  project.createSourceFile(filename, source)

  await transform.apply({ project })

  return project.getSourceFileOrThrow(filename).getFullText()
}
