+      case '--list': flags.list=true; break
+      case '--print': flags.print=true; break
+      case '--transform': flags.transform=argv[++i]; break
+      default: if(!arg.startsWith('-')&&!pathSet){flags.path=arg;pathSet=true} break
+    }
+  }
+  return flags
+}
